package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class LitWallCacheTest {
 public static void main(String[] args)throws Exception{int scenes=0,walls=0;long texels=0;try(DirectoryStream<Path> paths=Files.newDirectoryStream(Paths.get(args[0]),"source-race-background-*.nrb")){for(Path path:paths){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(path)).sky.scene;for(int owner=0;owner<scene.geometryCount();owner++){NativeScenePacket packet=scene.geometry(owner);NativeWorldScene world=new NativeWorldScene(packet);for(int index=0;index<world.surfaceCount();index++){NativeWorldScene.Surface s=world.surface(index);if(!s.lit)continue;NativeLitWall cache=new NativeLitWall(packet,world,index,new NativeWorldMesh(packet,world,index));ByteBuffer first=cache.variant(0);int before=first.hashCode();ByteBuffer states=s.states(),indices=s.originalIndices(),lighting=s.lighting();int pixels=s.width*s.height;for(int level=0;level<16;level++){ByteBuffer actual=cache.variant(level);if(!actual.isReadOnly()||actual.remaining()!=pixels*4)throw new AssertionError();for(int pixel=0;pixel<pixels;pixel++){int state=states.get((level+1)*pixels+pixel)&255;for(int c=0;c<3;c++){int expected=indices!=null?(c==0?indices.get((level+1)*pixels+pixel)&255:0):lighting.get(20+(level*pixels+pixel)*4+c)&255;if((actual.get(pixel*4+c)&255)!=expected)throw new AssertionError("Shading source changed");}if((actual.get(pixel*4+3)&255)!=(state==0?0:state==1?128:255))throw new AssertionError("Shading write state changed");texels++;}actual.position(actual.limit());if(cache.variant(level).position()!=0)throw new AssertionError("Variant position shared");}if(first.hashCode()!=before)throw new AssertionError("Eviction mutated older buffer");walls++;}}scenes++;}}if(scenes!=9||walls==0)throw new AssertionError("Missing wall scope");System.out.println("PASS_LIT_WALL_CACHE scenes="+scenes+" walls="+walls+" all_level_texels="+texels+" read_only_and_evicted_bytes_immutable=true");}
}
